  (* [comment removed for export] *)
  Lemma rs_join : forall m2 ws junk iS jr nsv tlv (x1 x5 x6 x7 x10 x11 x15 x16 x17 x19 x20 x21 x28 x29 x30 x31 : word),
    read_stats src = rs_tail ws (zlen ws) iS ->
    zlen ws <= 255 -> Forall (fun c => 0 <= c < 256) ws -> zlen junk = 256 - zlen ws ->
    u8arr psegs m2 RK jr -> zlen jr = 52 -> u8arr psegs m2 HW (map (Z_to_bv 8) ws ++ junk) ->
    rw_cells psegs m2 NSP [C4 nsv] -> rw_cells psegs m2 TLP [C4 tlv] ->
    rw_cells psegs m2 (FB + 8) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk psegs m2 lo FB -> wr_at psegs m FB 8 ->
    munch WALL m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
    lo <= FB - 384 -> 0 < HW -> HW + 256 <= lo -> 0 < RK -> RK + 52 <= lo -> SP + 8 <= NSP -> NSP + 4 <= TLP ->
    (HW + 256 <= RK \/ RK + 52 <= HW) ->
    evt psegs POST (MS (mkR x1 (Z_to_bv 64 FB) gp tp x5 x6 x7 (Z_to_bv 64 RK) (Z_to_bv 64 iS) x10 x11 (Z_to_bv 64 HW)
                            (Z_to_bv 64 NSP) (Z_to_bv 64 TLP) x15 x16 x17 (Z_to_bv 64 (zlen ws)) x19 x20 x21
                            s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
